const raw = $input.first().json.choices[0].message.content;
const imagesMatch = raw.match(/===IMAGES===([\s\S]*?)(===END===|$)/);
const imagesBlock = imagesMatch ? imagesMatch[1].trim() : '';
const lines = imagesBlock.split('\n').filter(l => l.trim().length > 0 && !/^none$/i.test(l.trim()));

if (lines.length === 0) {
  return [{ json: { prompt: null, skip: true } }];
}

return lines.map(line => {
  const m = line.match(/Prompt:\s*(.+)/i);
  return { json: { prompt: m ? m[1].trim() : line.trim(), skip: false } };
});

const raw = $node["HTTP Request"].json.choices[0].message.content;
const notesMatch = raw.match(/===NOTES===([\s\S]*?)(===IMAGES===|$)/);
const structuredText = notesMatch ? notesMatch[1].trim() : raw.replace(/===[A-Z]+===/g, '').trim();

const imagesMatch = raw.match(/===IMAGES===([\s\S]*?)(===END===|$)/);
const imagesBlock = imagesMatch ? imagesMatch[1].trim() : '';
const lines = imagesBlock.split('\n').filter(l => l.trim().length > 0 && !/^none$/i.test(l.trim()));
const imageConcepts = lines.map(line => {
  const m = line.match(/Concept:\s*(.+?)\s*\|/i);
  return m ? m[1].trim() : '';
});

function slugify(text) {
  return text.toLowerCase().trim().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
}

function markdownToHtml(md) {
  let html = md;
  html = html.replace(/^(#{1,6}) (.+)$/gm, (m, hashes, t) => {
    const level = Math.min(hashes.length, 6);
    return `<h${level} id="${slugify(t)}">${t}</h${level}>`;
  });
  html = html.replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>');
  html = html.replace(/`([^`]+)`/g, '<code>$1</code>');
  html = html.replace(/(^|\n)- (.+)/g, '$1<li>$2</li>');
  html = html.replace(/(<li>.*<\/li>\n?)+/gs, m => `<ul>${m}</ul>`);
  html = html.split('\n').map(line => {
    const t = line.trim();
    if (!t) return '';
    if (/^<h[1-6]|^<ul|^<li/.test(t)) return t;
    return `<p>${t}</p>`;
  }).join('\n');
  return html;
}

const html = markdownToHtml(structuredText);
console.log('CONVERTED HTML SAMPLE:', html.substring(0, 300));

const binary = {};
$input.all().forEach((item, i) => {
  binary['image' + i] = item.binary.data;
});
return [{ json: { html, imageConcepts }, binary }];

const item = $input.first();
const itemIndex = 0;

const html = item.json.html || '';
const concepts = item.json.imageConcepts || [];
const binary = item.binary || {};
const binaryKeys = Object.keys(binary);

function slugify(text) {
  return text.toLowerCase().trim().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
}

console.log('CONCEPTS:', concepts);
console.log('HEADING IDS FOUND:', [...html.matchAll(/id="([^"]+)"/g)].map(m => m[1]));

let finalHtml = html;
let leftoverImages = '';

for (let i = 0; i < binaryKeys.length; i++) {
  const key = binaryKeys[i];
  const buffer = await this.helpers.getBinaryDataBuffer(itemIndex, key);
  const imgData = buffer.toString('base64');
  const mimeType = binary[key]?.mimeType || 'image/jpeg';
  const imgTag = `<img src="data:${mimeType};base64,${imgData}"/>`;

  const concept = concepts[i];
  let placed = false;

  if (concept) {
    const slug = slugify(concept);
    const headingRegex = new RegExp(`(<h[1-6][^>]*id="${slug}"[^>]*>.*?<\\/h[1-6]>)`, 'i');
    if (headingRegex.test(finalHtml)) {
      finalHtml = finalHtml.replace(headingRegex, `$1${imgTag}`);
      placed = true;
    }
  }

  if (!placed) {
    leftoverImages += imgTag;
  }
}

const fullHtml = `<html><head><style>body{font-family:Georgia,serif;background:#fdfaf5;color:#3a3a3a;padding:40px;line-height:1.6;} h1,h2,h3{color:#6b8e7f;} img{max-width:100%;border-radius:8px;margin:16px 0;box-shadow:0 2px 8px rgba(0,0,0,0.1);}</style></head><body>${finalHtml}${leftoverImages}</body></html>`;

return [{ json: { fullHtml } }];
